import subprocess
import psycopg2
from psycopg2 import sql
_ALLOWED = {'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'}

def _normalize_privileges(privileges):
    cleaned = []
    for p in privileges:
        up = str(p).strip().upper()
        if up not in _ALLOWED:
            raise ValueError(f'Unsupported privilege: {p}')
        if up not in cleaned:
            cleaned.append(up)
    if not cleaned:
        raise ValueError('At least one privilege is required')
    return cleaned

def grant_postgres_table_privileges(dsn, schema, table, role, privileges, with_grant_option=False):
    privs = _normalize_privileges(privileges)
    query = sql.SQL('GRANT {privs} ON TABLE {tbl} TO {role}').format(privs=sql.SQL(', ').join((sql.SQL(p) for p in privs)), tbl=sql.Identifier(schema, table), role=sql.Identifier(role))
    if with_grant_option:
        query = query + sql.SQL(' WITH GRANT OPTION')
    conn = psycopg2.connect(dsn)
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(query)
    finally:
        conn.close()
    # Refresh planner statistics on the table after the access change
    subprocess.run(['psql', dsn, '-c', 'ANALYZE ' + schema.replace('"', '""') and 'ANALYZE "{}"."{}"'.format(schema.replace('"', '""'), table.replace('"', '""'))], check=False, capture_output=True, timeout=120)
    return {'schema': schema, 'table': table, 'role': role, 'privileges': privs, 'with_grant_option': bool(with_grant_option)}
